sksl:
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float time;
uniform float amount;
uniform float speed;
float4 readInput(float2 uv){if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return float4(0.0);return float4(image.eval(uv * size));}
half4 main(float2 coord){float2 uv=(coord / size);float n=sin(floor(uv.y*25.0)*91.7+floor(time*speed)*12.3);uv.x+=n*amount;float4 c=readInput(uv),r=readInput(uv+float2(amount,0.0)),b=readInput(uv-float2(amount,0.0));float a=max(c.a,max(r.a,b.a));return float4(r.r,c.g,b.b,a);}
